CREATE OR REPLACE FUNCTION public.reassign_finance_statement_account_v1(_tenant_id uuid, _import_id uuid, _account_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  statement_import public.finance_statement_imports%rowtype;
  old_account uuid;
  entry_ids uuid[];
  actor_name text;
begin
  perform finance_private.require_access(_tenant_id);
  if length(btrim(coalesce(_reason,'')))<10 then
    raise exception 'reason_required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':finance',0));
  select * into statement_import
  from public.finance_statement_imports
  where tenant_id=_tenant_id and id=_import_id
  for update;
  if not found then raise exception 'statement_not_found';end if;
  old_account:=statement_import.bank_account_id;
  if not exists(
    select 1 from public.bank_accounts
    where tenant_id=_tenant_id and id=_account_id and active and account_type<>'cash'
  ) then raise exception 'invalid_target_account';end if;
  select array_agg(id) into entry_ids
  from public.finance_bank_entries
  where tenant_id=_tenant_id and first_import_id=_import_id;
  if exists(
    select 1 from public.finance_reconciliation_groups
    where tenant_id=_tenant_id and bank_entry_ids && coalesce(entry_ids,'{}'::uuid[])
  ) then raise exception 'statement_already_reconciled';end if;
  if exists(
    select 1
    from public.finance_statement_identity_reviews review
    join public.finance_statement_rows statement_row
      on statement_row.tenant_id=review.tenant_id and statement_row.id=review.row_id
    where statement_row.import_id=_import_id
  ) then raise exception 'statement_identity_review_exists';end if;
  update public.finance_statement_imports
    set bank_account_id=_account_id
  where tenant_id=_tenant_id and id=_import_id;
  update public.finance_bank_entries
    set bank_account_id=_account_id
  where tenant_id=_tenant_id and first_import_id=_import_id;
  select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text)
    into actor_name from auth.users where id=auth.uid();
  insert into public.finance_events(
    tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data
  ) values (
    _tenant_id,'statement_import',_import_id,'statement_account_reassigned',auth.uid(),
    coalesce(actor_name,auth.uid()::text),btrim(_reason),
    jsonb_build_object('bank_account_id',old_account),
    jsonb_build_object('bank_account_id',_account_id,'manual_intervention',true)
  );
  return jsonb_build_object('confirmed',true,'import_id',_import_id,'bank_account_id',_account_id);
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.payable_movement_options(_tenant uuid, _payable uuid, _search text DEFAULT ''::text, _page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;result jsonb;paid numeric;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _page is null or _page not between 1 and 1000000 or length(coalesce(_search,''))>200 then raise exception 'finance_invalid_options' using errcode='22023';end if;
 select * into p from public.payables where id=_payable and tenant_id=_tenant;
 if not found then raise exception 'finance_payable_not_found' using errcode='22023';end if;
 select coalesce(sum(amount),0) into paid from finance_private.active_payable_payments where tenant_id=_tenant and payable_id=_payable;
 with candidates as materialized (
  select m.id,m.beneficiary_name,m.description,m.occurred_on,m.bank_reference,m.bank_account_id,b.name account_name,
   m.amount_cents::text amount_cents,(m.amount_cents-finance_private.movement_used_cents(_tenant,m.id))::text remaining_cents
  from finance_private.active_movements m join public.bank_accounts b on b.id=m.bank_account_id and b.tenant_id=_tenant
  where m.tenant_id=_tenant and m.direction='out' and m.nature<>'transfer'
   and (p.driver_id is null or m.driver_id=p.driver_id)
   and m.amount_cents>finance_private.movement_used_cents(_tenant,m.id)
   and position(lower(coalesce(_search,'')) in lower(m.beneficiary_name||' '||m.description||' '||coalesce(m.bank_reference,'')||' '||b.name||' '||m.id::text))>0
 ), paged as(select * from candidates order by occurred_on desc,id limit 30 offset (_page-1)*30)
 select jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'page',_page,'total',(select count(*) from candidates),
  'payable_status',p.status,'payable_name',p.supplier_name,'remaining_cents',(greatest(p.amount-paid,0)*100)::numeric(30,0)::text,
  'can_apply',p.status in('approved','partial') and paid>=0 and paid=trunc(paid,2) and p.amount>paid,
  'rows',coalesce((select jsonb_agg(to_jsonb(row) order by row.occurred_on desc,row.id) from paged row),'[]')) into result;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION finance_private.payable_payment_history(_tenant uuid, _payable uuid, _page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _page is null or _page not between 1 and 1000000 then raise exception 'finance_invalid_page' using errcode='22023';end if;
 if not exists(select 1 from public.payables where tenant_id=_tenant and id=_payable) then raise exception 'finance_payable_not_found' using errcode='22023';end if;
 with payments as materialized(select p.*,b.name account_name,l.id link_id,l.movement_id,l.origin link_origin,
  case when r.id is null then null else jsonb_build_object('id',r.id,'actor_id',r.created_by,'actor_name',r.actor_name,'reason',r.reason,'created_at',r.created_at) end reversal
  from public.payables_payments p left join public.bank_accounts b on b.id=p.bank_account_id and b.tenant_id=_tenant
  left join lateral(select l.* from public.finance_payable_movement_links l where l.payment_id=p.id and l.tenant_id=_tenant
 order by exists(select 1 from public.finance_payable_link_reversals rv where rv.tenant_id=l.tenant_id and rv.link_id=l.id),l.created_at desc,l.id desc limit 1) l on true
  left join public.finance_payable_link_reversals r on r.link_id=l.id and r.tenant_id=_tenant
  where p.tenant_id=_tenant and p.payable_id=_payable
 ), paged as(select * from payments order by paid_at desc,id desc limit 30 offset (_page-1)*30)
 select jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'page',_page,'total',(select count(*) from payments),
  'rows',coalesce((select jsonb_agg(to_jsonb(p) order by p.paid_at desc,p.id desc) from paged p),'[]')) into result;
 return result;
end;
$function$
